$base='http://localhost:3010'; $routes=@('/','/bodas','/proveedores','/proveedores/restaurante-ezkertza-berria','/fincas','/reservar/solista','/checkout/presupuesto','/artistas/edwin-agudelo'); foreach($r in $routes){ try { $s=(Invoke-WebRequest -Uri ($base+$r) -UseBasicParsing -TimeoutSec 60).StatusCode } catch { $s=$_.Exception.Response.StatusCode.value__ }; Write-Output ("{0}  {1}" -f $s,$r) }